// World model for W-bed R4 "group consolidation" (W-BED §3.4). A group of K subsidiaries closes at a consolidation date.
// Each subsidiary's month-end pack is an R1 or R3 task generated by that rung's own generate() from a child seed
// (children.mjs); the parent layer drawn here is the group: the group currency and closing-rate table, the subsidiary
// register, and each subsidiary's intercompany schedule (receivables due from and payables due to other group
// companies, with booking memos). The truth: which intercompany items are pairs (same counterparties, same currency and
// amount, memos describing the same charge for the same period), the translation of every pack and schedule, the
// eliminations and the consolidated report. The oracle, the reference pipeline and every control derive from
// buildGroup(seed, split, difficulty).
import { dayNum, lastDayOfMonth, isoDay, minorDigits, CURRENCIES, refKey } from '../lib/domain.mjs';
import { taskRng } from '../lib/prng.mjs';
import { hooks } from '../lib/faults.mjs';
import { COMPANY_STEMS } from '../lib/parties.mjs';
import { drawGroupRates } from '../lib/fx.mjs';
import { IC_KINDS, KIND_IDS, STYLES, PACKS, periodKey, prevPeriod } from './vocab.mjs';
import { childSeedOf, FAMILIES, reportDateOf, buildLedger, plantInputs, plantedTrace, plantableSystems, PLANTED_STYLE } from './children.mjs';
import { renderGroup } from './render.mjs';

// 1.0.1 (2026-10-14): no change of R4's own; its R3 children follow wbed-r3 1.1.0 (FX quotes stored at their printed
// precision), so tasks with an R3 pack print some quotes one in the fourth decimal higher and their US-cent totals move.
export const VERSION = '1.0.1';
export const MIN_D = 2, MAX_D = 5;

// Knobs per difficulty (W-BED §2.5 drift: subsidiaries, intercompany density, FX complexity, outside-profile rate).
//   K: subsidiaries; r3: how many are statement audits (W-BED: 1 in 4 at d >= 3, rounded up); planted: R1 packs
//   re-rendered in a date dialect no R1 stream saw (W-BED: 1 in 6; here 1/3, 1/4, 1/3 by count 1, 1, 2); childD: child
//   difficulty, clamped to 3..4 (R1/R3 streams run d3 then d4: every unplanted pack is from a distribution the earlier
//   rung's stream covered); pairs: plain intercompany pairs; siblings:
//   flat-fee pairs whose seller also booked the same fee for the previous period, which the buyer has not booked (equal
//   amounts, different period: amount-only pairing takes the wrong one); cross: equal-amount one-sided items of
//   different charges on both sides (amount-only pairing eliminates them); disputed: the same charge booked at different
//   amounts (memo-only pairing eliminates them); oneSided: items the other side has not booked; refQuoteP: share of
//   buyer memos that quote the seller's invoice number; dated: packs translated at their own reporting date's rate.
export const LEVELS = {
  2: { K: 2, r3: 0, planted: 0, childD: 3, pairs: 3, siblings: 1, cross: 1, disputed: 1, oneSided: 1, refQuoteP: 0.8, dated: false,
    styles: ['CSV', 'UK', 'DE'], currencies: ['USD', 'EUR', 'GBP'], groups: ['EUR', 'GBP'] },
  3: { K: 3, r3: 1, planted: 1, childD: 3, pairs: 4, siblings: 2, cross: 1, disputed: 1, oneSided: 2, refQuoteP: 0.4, dated: false,
    styles: ['CSV', 'UK', 'DE', 'JSON', 'CH'], currencies: ['USD', 'EUR', 'GBP', 'CHF'], groups: ['EUR', 'GBP'] },
  4: { K: 4, r3: 1, planted: 1, childD: 4, pairs: 6, siblings: 2, cross: 2, disputed: 2, oneSided: 2, refQuoteP: 0.2, dated: true,
    styles: ['CSV', 'UK', 'DE', 'JSON', 'CH'], currencies: ['USD', 'EUR', 'GBP', 'CHF'], groups: ['EUR', 'GBP'] },
  5: { K: 6, r3: 2, planted: 2, childD: 4, pairs: 10, siblings: 3, cross: 3, disputed: 2, oneSided: 3, refQuoteP: 0, dated: true,
    styles: ['CSV', 'UK', 'DE', 'JSON', 'CH', 'JP'], currencies: ['USD', 'EUR', 'GBP', 'CHF', 'JPY'], groups: ['EUR', 'GBP', 'CHF'] },
};
const RATE_CURRENCIES = ['USD', 'EUR', 'GBP', 'CHF', 'JPY'];

// ---------------------------------------------------------------------------------------------------------------------
// Children: fixed by (seed, split, difficulty); the parent's re-draws never touch them.
const childCache = new Map();
export function buildChildren(spec) {
  const key = JSON.stringify([spec.seed, spec.split, spec.difficulty]);
  if (childCache.has(key)) return childCache.get(key);
  const L = LEVELS[spec.difficulty];
  const r = taskRng('r4', 'children', spec);
  const slots = Array.from({ length: L.K }, (_, k) => k);
  const r3Slots = new Set(r.shuffle(slots).slice(0, L.r3));
  const kids = slots.map(k => {
    const family = r3Slots.has(k) ? 'wbed-r3' : 'wbed-r1';
    const cspec = { seed: childSeedOf(spec.seed, spec.difficulty, k), split: spec.split, difficulty: L.childD };
    const bed = FAMILIES[family];
    const task = bed.generate(cspec);
    return { k, id: `S${k + 1}`, family, pack: PACKS[family], spec: cspec, task, reportDate: reportDateOf(family, cspec),
      output: bed.referenceSolve(task), outsideProfile: false, planted: null };
  });
  // The plant: L.planted R1 children (in a seeded order) whose re-dated system changes the report when misread.
  const r1kids = r.shuffle(kids.filter(c => c.family === 'wbed-r1'));
  let need = L.planted;
  for (const c of r1kids) {
    if (!need) break;
    const w = buildLedger(c.spec.seed, c.spec.split, c.spec.difficulty);
    const ok = plantableSystems(w, c.output);
    if (!ok.length) continue;
    const S = r.pick(ok);
    const inputs = plantInputs(w, c.task.inputs, S);
    c.task = { ...c.task, id: `${c.task.id}/${PLANTED_STYLE}:${S}`, inputs };
    c.outsideProfile = true;
    c.planted = { system: S, style: PLANTED_STYLE };
    need--;
  }
  if (need) throw new Error(`wbed-r4: seed ${spec.seed} d${spec.difficulty}: no plantable R1 pack (${need} missing)`);
  childCache.set(key, kids);
  if (childCache.size > 96) childCache.delete(childCache.keys().next().value);
  return kids;
}

/** The exact trace of a child (its rung's referenceTrace; planted children carry the dialect's surface text). */
export function childTruthTrace(kid) {
  const bed = FAMILIES[kid.family];
  const tr = bed.referenceTrace(kid.task);
  if (!kid.planted) return tr;
  return plantedTrace(buildLedger(kid.spec.seed, kid.spec.split, kid.spec.difficulty), tr, kid.planted.system);
}

// ---------------------------------------------------------------------------------------------------------------------
const worldCache = new Map();
let verifier = null;
export function setVerifier(fn) { verifier = fn; }

export function buildGroup(seed, split = 'dev', difficulty = 3) {
  const key = JSON.stringify([seed, split, difficulty]);
  if (worldCache.has(key)) return worldCache.get(key);
  if (!LEVELS[difficulty]) throw new Error(`wbed-r4: difficulty must be ${MIN_D}..${MAX_D}, got ${difficulty}`);
  if (split !== 'dev' && split !== 'test') throw new Error(`wbed-r4: split must be 'dev' or 'test', got ${split}`);
  const spec = { seed, split, difficulty };
  const kids = buildChildren(spec);
  let world = null, last = null;
  for (let attempt = 0; attempt < 60 && !world; attempt++) {
    const w = attemptGroup(spec, kids, attempt);
    if (w.reject) { last = w.reject; continue; }
    world = w;
  }
  if (!world) throw new Error(`wbed-r4: no valid group for seed ${seed} d${difficulty} (${last})`);
  worldCache.set(key, world);
  if (worldCache.size > 96) worldCache.delete(worldCache.keys().next().value);
  return world;
}

const periodOrd = p => (p.kind === 'month' ? p.m : 3 * p.q);

function attemptGroup(spec, kids, attempt) {
  const L = LEVELS[spec.difficulty];
  const r = taskRng('r4', 'group', spec, attempt);
  const reject = reason => ({ reject: reason });

  const groupCurrency = r.pick(L.groups);
  const groupMonth = r.int(9, 10);
  const groupDate = lastDayOfMonth(2025, groupMonth);

  // Subsidiaries: house style (book currency, side words, number format) and names.
  const stems = r.shuffle(COMPANY_STEMS.filter(s => s.length >= 4));
  const prefixes = new Set();
  const styles = kids.map(() => r.pick(L.styles));
  if (L.styles.includes('JP') && !styles.includes('JP')) styles[r.int(0, styles.length - 1)] = 'JP';
  const subs = kids.map((kid, i) => {
    const style = styles[i], st = STYLES[style];
    let stem = stems[i], prefix = `H${stem.slice(0, 2).toUpperCase()}`;
    for (let j = L.K; prefixes.has(prefix); j++) { stem = stems[j]; prefix = `H${stem.slice(0, 2).toUpperCase()}`; }
    prefixes.add(prefix);
    return { ...kid, idx: i, style, book: st.book, stem, prefix, name: `Hollin ${stem} ${st.legal}`, short: `Hollin ${stem}` };
  });

  // Closing rates: one table at the consolidation date, or (dated) one per month end from March to the consolidation month.
  const dateKeys = L.dated ? Array.from({ length: groupMonth - 2 }, (_, i) => isoDay(lastDayOfMonth(2025, 3 + i))) : [isoDay(groupDate)];
  const rates = drawGroupRates(r, groupCurrency, RATE_CURRENCIES.filter(c => L.currencies.includes(c) || c === 'USD'), dateKeys);
  for (const kid of kids) if (!rates[L.dated ? isoDay(kid.reportDate) : isoDay(groupDate)]) return reject('no-rate-for-pack-date');

  // ---- intercompany items
  const items = [];
  const used = new Set(), refs = new Set();
  const months = Array.from({ length: groupMonth }, (_, i) => ({ kind: 'month', m: i + 1 }));
  const quarters = [1, 2, 3].map(q => ({ kind: 'quarter', q }));
  const periodsOf = kind => (IC_KINDS[kind].period === 'month' ? months : quarters);
  const keyOf = (A, B, kind, p) => `${A.id}|${B.id}|${kind}|${periodKey(p)}`;
  const pickPair = () => { const A = r.pick(subs); const B = r.pick(subs.filter(x => x !== A)); return [A, B]; };
  const currencyFor = (A, B) => {
    const c = r.chance(0.5) ? A.book : r.chance(0.6) ? B.book : r.pick(['EUR', 'USD']);
    return L.currencies.includes(c) ? c : 'EUR';
  };
  const amountFor = (cur, fixed) => {
    const units = Math.exp(r.float(Math.log(1500), Math.log(60000))) / CURRENCIES[cur].rate;
    const md = minorDigits(cur);
    if (fixed) return Math.max(1, Math.round(units / 100)) * 100 * 10 ** md;
    return Math.max(1, Math.round(units * 10 ** md));
  };
  const newRef = A => { for (;;) { const s = `${A.prefix}-IC-${r.int(1000, 9999)}`; if (!refs.has(refKey(s))) { refs.add(refKey(s)); return s; } } };
  const drawCharge = (A, B, { fixed = null, needPrev = false, avoidKind = null } = {}) => {
    for (let t = 0; t < 80; t++) {
      const kind = r.pick(KIND_IDS.filter(k => (fixed === null || IC_KINDS[k].fixed === fixed) && k !== avoidKind));
      const p = r.pick(periodsOf(kind));
      if (used.has(keyOf(A, B, kind, p))) continue;
      if (needPrev) { const pp = prevPeriod(p); if (!pp || used.has(keyOf(A, B, kind, pp))) continue; }
      return { kind, period: p };
    }
    return null;
  };
  let txnN = 0;
  const add = (A, B, side, c, currency, minor, role, txn, ref) => {
    items.push({ sub: side === 'R' ? A.id : B.id, cp: side === 'R' ? B.id : A.id, side, kind: c.kind, period: c.period, currency, minor, role, txn, ref, seller: A.id });
  };
  const truePair = (A, B, c, currency, minor, role) => {
    used.add(keyOf(A, B, c.kind, c.period));
    const txn = `T${++txnN}`, ref = newRef(A);
    add(A, B, 'R', c, currency, minor, role, txn, ref);
    add(A, B, 'P', c, currency, minor, role, txn, ref);
    return txn;
  };
  for (let i = 0; i < L.pairs; i++) {
    const [A, B] = pickPair(); const c = drawCharge(A, B); if (!c) return reject('pair-charge');
    const cur = currencyFor(A, B); truePair(A, B, c, cur, amountFor(cur, IC_KINDS[c.kind].fixed), 'pair');
  }
  for (let i = 0; i < L.siblings; i++) {
    const [A, B] = pickPair(); const c = drawCharge(A, B, { fixed: true, needPrev: true }); if (!c) return reject('sibling-charge');
    const cur = currencyFor(A, B), minor = amountFor(cur, true);
    truePair(A, B, c, cur, minor, 'pair');
    const pc = { kind: c.kind, period: prevPeriod(c.period) };
    used.add(keyOf(A, B, pc.kind, pc.period));
    add(A, B, 'R', pc, cur, minor, 'sibling-decoy', null, newRef(A));
  }
  for (let i = 0; i < L.cross; i++) {
    const [A, B] = pickPair(); const x = drawCharge(A, B); if (!x) return reject('cross-charge');
    used.add(keyOf(A, B, x.kind, x.period));
    const y = drawCharge(A, B, { avoidKind: x.kind }); if (!y) return reject('cross-charge');
    used.add(keyOf(A, B, y.kind, y.period));
    const cur = currencyFor(A, B), minor = amountFor(cur, IC_KINDS[x.kind].fixed || IC_KINDS[y.kind].fixed);
    add(A, B, 'R', x, cur, minor, 'cross-decoy', null, newRef(A));   // billed, not yet booked by B
    add(A, B, 'P', y, cur, minor, 'cross-decoy', null, null);        // accrued by B, not yet billed by A
  }
  for (let i = 0; i < L.disputed; i++) {
    const [A, B] = pickPair(); const c = drawCharge(A, B); if (!c) return reject('disputed-charge');
    used.add(keyOf(A, B, c.kind, c.period));
    const cur = currencyFor(A, B), minor = amountFor(cur, false);
    const booked = Math.max(1, Math.round(minor * r.float(0.85, 0.97)));
    if (booked === minor) return reject('disputed-equal');
    const ref = newRef(A), txn = `D${i + 1}`;
    add(A, B, 'R', c, cur, minor, 'disputed', txn, ref);
    add(A, B, 'P', c, cur, booked, 'disputed', txn, ref);
  }
  for (let i = 0; i < L.oneSided; i++) {
    const [A, B] = pickPair(); const c = drawCharge(A, B); if (!c) return reject('one-sided-charge');
    used.add(keyOf(A, B, c.kind, c.period));
    const cur = currencyFor(A, B), side = r.chance(0.5) ? 'R' : 'P';
    add(A, B, side, c, cur, amountFor(cur, IC_KINDS[c.kind].fixed), 'one-sided', null, side === 'R' ? newRef(A) : null);
  }
  if (!items.some(x => x.currency !== groupCurrency && (x.role === 'pair'))) return reject('all-pairs-in-group-currency');

  // Schedule order per subsidiary: counterparty, receivables first, period, charge kind; then item ids.
  const subIdx = new Map(subs.map(s => [s.id, s.idx]));
  const ordered = [];
  for (const s of subs) {
    const mine = r.shuffle(items.filter(x => x.sub === s.id));
    mine.sort((a, b) => (subIdx.get(a.cp) - subIdx.get(b.cp)) || a.side.localeCompare(b.side) * -1 || (periodOrd(a.period) - periodOrd(b.period)) || a.kind.localeCompare(b.kind));
    mine.forEach((x, i) => { x.id = `IC-${s.id}-${String(i + 1).padStart(2, '0')}`; ordered.push(x); });
  }

  // Truth pairs, recomputed from item attributes by the stated rule (and checked against the construction).
  const pairs = referencePairs(ordered);
  const built = ordered.filter(x => x.side === 'R' && x.role === 'pair').length;
  if (pairs.length !== built) return reject('pair-rule-mismatch');

  let world = { spec, attempt, L, groupCurrency, groupMonth, groupDate, dateKeys, rates, subs, items: ordered, pairs };
  world = hooks.schemaDrift(world); // R8 f1 hook point (no-op in v1)
  if (verifier) {
    const bad = verifier(world);
    if (bad) return reject(`control-passes:${bad}`);
  }
  world.render = renderGroup(world);
  return world;
}

/** The stated pairing rule over item attributes: X's receivable against Y and Y's payable against X, same currency and
 *  amount, same charge kind and period. Each item in at most one pair (the generator makes the match unique). */
export function referencePairs(items) {
  const out = [];
  const taken = new Set();
  for (const a of items) {
    if (a.side !== 'R') continue;
    const m = items.filter(b => b.side === 'P' && b.sub === a.cp && b.cp === a.sub && b.currency === a.currency && b.minor === a.minor
      && b.kind === a.kind && periodKey(b.period) === periodKey(a.period) && !taken.has(b.id));
    if (m.length > 1) throw new Error(`wbed-r4: ambiguous pair for ${a.id}`);
    if (m.length === 1) { taken.add(m[0].id); out.push({ receivable_item: a.id, payable_item: m[0].id }); }
  }
  return out;
}

export const rateKeyOf = (world, day) => (world.L.dated ? isoDay(day) : isoDay(world.groupDate));
export { dayNum };
